//! Static & Point-in-Time QMV Universe Taxonomy (`3 Sector Groups × 11 Sectors × DT1/DT2/DT3 × QMV30/60`).
//!
//! Synchronized from Yumeko's QMV V7 reference tables (`division_current`, `qmv60_membership`,
//! and `KNOWLEDGE_MANIFEST.json`) plus dynamic causal `PriceTier` / `LiquidityTier` classifiers.
//! Pure `no_std`-style `const` lookup (`wasm32-unknown-unknown` compatible, zero heap allocation).

use serde::{Deserialize, Serialize};

/// QMV Macro-Cycle Sector Group (`3 Nhóm ngành chu kỳ QMV`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum QmvSectorGroup {
    /// Nhóm ngành 1: Nhạy lãi suất & Đòn bẩy tài chính (Ngân hàng, Chứng khoán, BĐS, XD & Thép).
    Group1FinancialLeverage,
    /// Nhóm ngành 2: Đòn bẩy hoạt động & Chu kỳ KQKD (Bán lẻ, Công nghệ, KCN/Cảng, Dầu khí/Hóa chất, F&B...).
    Group2OperatingCycle,
    /// Nhóm ngành 3: Phòng thủ & Bão hòa (Điện, Nước, Bảo hiểm, Dược/Y tế).
    Group3Defensive,
    /// Chỉ số thị trường & Phái sinh.
    MarketIndex,
}

impl QmvSectorGroup {
    #[inline]
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Self::Group1FinancialLeverage => "GROUP_1",
            Self::Group2OperatingCycle => "GROUP_2",
            Self::Group3Defensive => "GROUP_3",
            Self::MarketIndex => "INDEX",
        }
    }

    #[inline]
    #[must_use]
    pub const fn label_vi(self) -> &'static str {
        match self {
            Self::Group1FinancialLeverage => "Nhóm ngành 1 (Tài chính & Đòn bẩy)",
            Self::Group2OperatingCycle => "Nhóm ngành 2 (Chu kỳ & Tăng trưởng)",
            Self::Group3Defensive => "Nhóm ngành 3 (Phòng thủ & Tiện ích)",
            Self::MarketIndex => "Chỉ số & Phái sinh",
        }
    }

    #[must_use]
    pub fn parse_str(raw: &str) -> Option<Self> {
        match raw.trim().to_ascii_uppercase().as_str() {
            "1" | "GROUP_1" | "GROUP1" | "NHOM_1" => Some(Self::Group1FinancialLeverage),
            "2" | "GROUP_2" | "GROUP2" | "NHOM_2" => Some(Self::Group2OperatingCycle),
            "3" | "GROUP_3" | "GROUP3" | "NHOM_3" => Some(Self::Group3Defensive),
            "INDEX" => Some(Self::MarketIndex),
            _ => None,
        }
    }
}

