/// QMV Institutional Money-Flow Tier (`DT1 / DT2 / DT3` — Ma trận 9 Quả Bóng DM01).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum QmvMoneyTier {
    /// DT1: Cổ phiếu Tạo lập / Large-cap dẫn dắt chất lượng cao.
    Dt1,
    /// DT2: Mid-cap tăng trưởng / lan tỏa thân sóng.
    Dt2,
    /// DT3: Small-cap / Đầu cơ / Trà đá cuối sóng (cấm bắt đáy theo `qmv-kt01-bot-010`).
    Dt3,
    /// Chỉ số hoặc mã ngoài phân lớp cơ sở.
    IndexOrOther,
}

impl QmvMoneyTier {
    #[inline]
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Self::Dt1 => "DT1",
            Self::Dt2 => "DT2",
            Self::Dt3 => "DT3",
            Self::IndexOrOther => "OTHER",
        }
    }

    #[inline]
    #[must_use]
    pub const fn label_vi(self) -> &'static str {
        match self {
            Self::Dt1 => "DT1 (Tạo lập / Dẫn dắt)",
            Self::Dt2 => "DT2 (Mid-cap Lan tỏa)",
            Self::Dt3 => "DT3 (Small-cap / Đầu cơ)",
            Self::IndexOrOther => "Chỉ số / Khác",
        }
    }

    #[must_use]
    pub fn parse_str(raw: &str) -> Option<Self> {
        match raw.trim().to_ascii_uppercase().as_str() {
            "DT1" => Some(Self::Dt1),
            "DT2" => Some(Self::Dt2),
            "DT3" => Some(Self::Dt3),
            "OTHER" | "INDEX" => Some(Self::IndexOrOther),
            _ => None,
        }
    }
}

/// Causal Point-in-Time QMV V7 Price Tier (`Phân loại Thị giá: Trà đá <10k, 10–30k, 30–50k, ≥50k`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum QmvPriceTier {
    /// Trà đá (`< 10,000 VND`).
    PennyUnder10k,
    /// Thị giá thấp–vừa (`10,000 .. < 30,000 VND`).
    Low10To30k,
    /// Thị giá trung bình (`30,000 .. < 50,000 VND`).
    Mid30To50k,
    /// Thị giá cao (`>= 50,000 VND`).
    High50kPlus,
}

impl QmvPriceTier {
    /// Classifies a close price (auto-normalizing both raw VND `46850.0` and `'000 VND` `46.85`).
    #[inline]
    #[must_use]
    pub fn from_close_price(close: f64) -> Self {
        let vnd = if close > 0.0 && close < 500.0 {
            close * 1_000.0
        } else {
            close
        };
        if vnd < 10_000.0 {
            Self::PennyUnder10k
        } else if vnd < 30_000.0 {
            Self::Low10To30k
        } else if vnd < 50_000.0 {
            Self::Mid30To50k
        } else {
            Self::High50kPlus
        }
    }

    #[inline]
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Self::PennyUnder10k => "UNDER_10K",
            Self::Low10To30k => "10K_30K",
            Self::Mid30To50k => "30K_50K",
            Self::High50kPlus => "OVER_50K",
        }
    }

    #[inline]
    #[must_use]
    pub const fn label_vi(self) -> &'static str {
        match self {
            Self::PennyUnder10k => "Trà đá (< 10k)",
            Self::Low10To30k => "10k – 30k",
            Self::Mid30To50k => "30k – 50k",
            Self::High50kPlus => "≥ 50k",
        }
    }

    #[must_use]
    pub fn parse_str(raw: &str) -> Option<Self> {
        match raw.trim().to_ascii_uppercase().as_str() {
            "UNDER_10K" | "PENNY" | "TRA_DA" => Some(Self::PennyUnder10k),
            "10K_30K" => Some(Self::Low10To30k),
            "30K_50K" => Some(Self::Mid30To50k),
            "OVER_50K" | "50K_PLUS" => Some(Self::High50kPlus),
            _ => None,
        }
    }
}

/// Causal Point-in-Time 20-bar Average Volume Tier (`Ngưỡng thanh khoản QMV V7: ≥50,000 cp/phiên`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum QmvLiquidityTier {
    /// `< 10,000` cp/phiên — Thanh khoản cạn kiệt (loại khỏi giải ngân chuẩn QMV).
    IlliquidUnder10k,
    /// `10,000 .. < 50,000` cp/phiên — Thanh khoản nhỏ.
    Small10kTo50k,
    /// `50,000 .. < 1,000,000` cp/phiên — Thanh khoản vừa (đạt chuẩn QMV V7).
    Standard50kTo1M,
    /// `>= 1,000,000` cp/phiên — Thanh khoản lớn.
    High1MPlus,
}

impl QmvLiquidityTier {
    #[inline]
    #[must_use]
    pub fn from_avg_vol_20(avg_vol_20: f64) -> Self {
        if !avg_vol_20.is_finite() || avg_vol_20 < 10_000.0 {
            Self::IlliquidUnder10k
        } else if avg_vol_20 < 50_000.0 {
            Self::Small10kTo50k
        } else if avg_vol_20 < 1_000_000.0 {
            Self::Standard50kTo1M
        } else {
            Self::High1MPlus
        }
    }

    #[inline]
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Self::IlliquidUnder10k => "UNDER_10K_VOL",
            Self::Small10kTo50k => "10K_50K_VOL",
            Self::Standard50kTo1M => "50K_1M_VOL",
            Self::High1MPlus => "OVER_1M_VOL",
        }
    }
}

/// Static QMV metadata profile for a Vietnam equity symbol.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct QmvSymbolProfile {
    pub symbol: &'static str,
    pub sector_group: QmvSectorGroup,
    pub sector: QmvSector,
    pub money_tier: QmvMoneyTier,
    pub in_qmv30: bool,
    pub in_qmv60: bool,
    pub in_yumeko_core10: bool,
    /// `true` when sourced directly from Yumeko QMV reference tables; `false` when inferred via ICB/ADTV rules.
    pub exact_yumeko_tier: bool,
}

