/// Strips optional `"EXCHANGE:"` prefix (`"HOSE:FPT" -> "FPT"`) and looks up its [`QmvSymbolProfile`].
#[must_use]
pub fn lookup_qmv_profile(ticker_or_symbol: &str) -> Option<&'static QmvSymbolProfile> {
    let trimmed = ticker_or_symbol.trim();
    let raw_sym = match trimmed.rsplit_once(':') {
        Some((_, s)) => s.trim(),
        None => trimmed,
    };
    if raw_sym.is_empty() {
        return None;
    }
    QMV_SYMBOL_PROFILES
        .binary_search_by(|entry| {
            entry
                .symbol
                .bytes()
                .cmp(raw_sym.bytes().map(|b| b.to_ascii_uppercase()))
        })
        .ok()
        .map(|idx| &QMV_SYMBOL_PROFILES[idx])
}

/// Returns `true` if `exchange` belongs to the Vietnam stock/derivatives market (`HOSE`, `HNX`, `UPCOM`).
#[inline]
#[must_use]
pub fn is_vn_exchange(exchange: &str) -> bool {
    matches!(
        exchange.trim().to_ascii_uppercase().as_str(),
        "HOSE" | "HSX" | "HNX" | "UPCOM"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn symbol_profiles_are_strictly_sorted_for_binary_search() {
        for pair in QMV_SYMBOL_PROFILES.windows(2) {
            assert!(
                pair[0].symbol < pair[1].symbol,
                "QMV_SYMBOL_PROFILES out of order: {} >= {}",
                pair[0].symbol,
                pair[1].symbol
            );
        }
    }

    #[test]
    fn lookup_resolves_prefixed_and_bare_tickers_and_baskets() {
        let fpt = lookup_qmv_profile("HOSE:FPT").expect("FPT profile");
        assert_eq!(fpt.sector, QmvSector::TechnologyTelecom);
        assert_eq!(fpt.money_tier, QmvMoneyTier::Dt1);
        assert!(fpt.in_qmv30 && fpt.in_qmv60 && fpt.in_yumeko_core10);

        let hpg = lookup_qmv_profile("hpg").expect("HPG profile");
        assert_eq!(hpg.sector, QmvSector::ConstructionSteel);
        assert_eq!(hpg.money_tier, QmvMoneyTier::Dt1);
        assert!(hpg.in_qmv30);

        assert_eq!(QMV30_SYMBOLS.len(), 30);
        assert_eq!(QMV60_SYMBOLS.len(), 60);
        assert_eq!(YUMEKO_CORE10_SYMBOLS.len(), 10);
        for sym in QMV60_SYMBOLS {
            assert!(lookup_qmv_profile(sym).expect(sym).in_qmv60);
        }
    }

    #[test]
    fn price_and_liquidity_tiers_classify_vnd_and_thousand_vnd() {
        assert_eq!(
            QmvPriceTier::from_close_price(8_500.0),
            QmvPriceTier::PennyUnder10k
        );
        assert_eq!(
            QmvPriceTier::from_close_price(8.5),
            QmvPriceTier::PennyUnder10k
        );
        assert_eq!(
            QmvPriceTier::from_close_price(24_500.0),
            QmvPriceTier::Low10To30k
        );
        assert_eq!(
            QmvPriceTier::from_close_price(62_000.0),
            QmvPriceTier::High50kPlus
        );
        assert_eq!(
            QmvLiquidityTier::from_avg_vol_20(8_000.0),
            QmvLiquidityTier::IlliquidUnder10k
        );
        assert_eq!(
            QmvLiquidityTier::from_avg_vol_20(120_000.0),
            QmvLiquidityTier::Standard50kTo1M
        );
        assert_eq!(
            QmvLiquidityTier::from_avg_vol_20(2_500_000.0),
            QmvLiquidityTier::High1MPlus
        );
    }
}
